#!/usr/bin/env bash
# AKFC — Demandes (tickets), incrément 4 : relève de noreply@ (IMAP) → réponses des demandeurs
# ajoutées au fil de leur demande.
#  - dépendances (racine) : imapflow 2.2.9, mailparser 3.9.36 (+ @types/mailparser en dev)
#  - rattachement : en-têtes de réponse (Message-ID de nos réponses), sinon [AKFC-0042] de l'objet ;
#    expéditeur = adresse du demandeur obligatoire ; citation retirée ; pièces jointes signalées ;
#    absences / rebonds / listes jamais ajoutés ; une demande close est rouverte.
#  - dossiers IMAP : « Tickets traités », « Tickets à vérifier » (créés au besoin) ; le reste de
#    la boîte n'est pas déplacé (mot-clé $AkfcSkipped, état lu/non lu intact).
#  - avis au club « Nouveau message » (adresse de la catégorie, lien direct).
#  - relève active ⇔ TICKET_IMAP_HOST défini : accusés et réponses invitent alors à répondre à
#    noreply@ ; sinon rien ne change (Reply-To = admin@/support@).
#  Aucune migration. 2 fichiers des incréments 3a/3b remplacés seulement s'ils n'ont pas bougé.
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-tickets-increment4.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
T="packages/backend/src/modules/tickets"; E="packages/backend/src/email/services/sendTicketEmails.ts"
[ -f apps/web/src/features/tickets/ticketUi.ts ] || { echo "ERREUR: applique d'abord apply-tickets-increment3b.sh." >&2; exit 1; }
[ -f "$T/inboundEmail.ts" ] && { echo "— déjà appliqué"; exit 0; }
declare -A SUM=(
  ["$E"]="f1d6e7bf8a4701ede3e94b4a063465270c0b982b1e5bd221414b0eafae6845c7"
  ["$T/ticketQueries.service.ts"]="9c1546b268805a9b337849264e163cfb590b3dca9c4626eaab2ff4400df77a6d"
)
for f in "${!SUM[@]}"; do
  [ "$(sha256sum "$f" | cut -c1-64)" = "${SUM[$f]}" ] || { echo "ERREUR: $f a été modifié depuis sa livraison — rien n'est touché. Envoie-le moi." >&2; exit 1; }
done
EDITED=(apps/web/src/instrumentation.ts "apps/web/src/app/(admin)/dashboard/tickets/[id]/page.tsx" apps/web/next.config.ts package.json pnpm-lock.yaml)
BK=/tmp/akfc_tk4_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${!SUM[@]}" "${EDITED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${!SUM[@]}" "${EDITED[@]}"; do cp "$BK/$f" "$f"; done; rm -f "$T/inboundEmail.ts" "$T/imapIntake.service.ts"; echo "↩ fichiers restaurés à l'identique (aucun commit). Lance « pnpm install » pour réaligner node_modules."; }

W=/tmp/akfc_tk4; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"

echo "== dépendances =="
if ! { pnpm add -w imapflow@2.2.9 mailparser@3.9.36 >/tmp/akfc_dep.log 2>&1 && pnpm add -Dw @types/mailparser@3.9.0 >>/tmp/akfc_dep.log 2>&1; }; then
  echo "❌ installation impossible :"; tail -8 /tmp/akfc_dep.log; restore; exit 1
fi
echo "  ok  imapflow, mailparser, @types/mailparser"

echo "== application =="
echo '' | base64 -d > "$E"
echo '' | base64 -d > "$T/ticketQueries.service.ts"
echo '' | base64 -d > "$T/inboundEmail.ts"
echo '' | base64 -d > "$T/imapIntake.service.ts"
echo "  ok  2 fichiers mis à jour, 2 créés"
python3 "$W/edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

git add "$T" "$E" "${EDITED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(tickets): relève IMAP de noreply@ — réponses des demandeurs rattachées à leur demande

